#! /bin/bash

set -euo pipefail

ROOT=$(cd "$(dirname "$0")/.."; pwd)
DEST="$ROOT/packages"

rm -rf "$DEST"
mkdir "$DEST"

webpack --config "$ROOT/webpack.config.js"

# Keep declarations for workspace development; .npmignore excludes them from publication.
mkdir "$DEST/ari/types"
# Bolt links workspace dependencies after root postinstall.
cp "$ROOT/../../node_modules/@atlassian/ari/index.d.ts" \
  "$ROOT/../../node_modules/@atlassian/ari/_tsup-dts-rollup.d.ts" "$DEST/ari/types/"
sed 's|@atlassian/ari|./types|' "$ROOT/src/ari.js" > "$DEST/ari/index.d.ts"
